import{stopPush}from"./admin-alerts.js?v=1.21.2";const $=selector=>document.querySelector(selector);const money=cents=>(cents/100).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});const escape=value=>String(value).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]);const stages=["new","accepted","preparing","ready","delivered"];const names={new:"Novo",accepted:"Aceito",preparing:"Preparando",ready:"Pronto",delivered:"Entregue",cancelled:"Cancelado"};const actions={new:"Aceitar pedido",accepted:"Come\xE7ar preparo",preparing:"Marcar pronto",ready:"Marcar entregue"};let state,timer,seen=new Set,firstLoad=true,audio,polling=false,ordersSignature;function feedback(message){$("#admin-feedback").textContent=message}async function api(path,method="GET",data){const response=await fetch("/api/admin/"+path,{method,headers:data?{"Content-Type":"application/json"}:{},body:data?JSON.stringify(data):void 0});const result=await response.json();if(!response.ok){if(response.status===401&&path!=="login")signedOut();throw new Error(result.error||"N\xE3o foi poss\xEDvel conectar.")}return result}function signedOut(){clearInterval(timer);$("#dashboard").hidden=true;$("#login-section").hidden=false;$("#logout").hidden=true;$("#panel-nav").hidden=true;state=void 0;window.dispatchEvent(new CustomEvent("renato:metrics",{detail:null}))}function beep(){if(!audio)return;const oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.connect(gain);gain.connect(audio.destination);oscillator.frequency.value=740;gain.gain.setValueAtTime(.12,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.5);oscillator.start();oscillator.stop(audio.currentTime+.5)}function renderOrders(){const ended=order=>["delivered","cancelled"].includes(order.status);const orders=state.orders.filter(order=>$("#show-history").checked||!ended(order)).sort((a,b)=>Number(ended(a))-Number(ended(b))||(ended(a)?b.id-a.id:a.id-b.id));$("#queue-count").textContent=state.orders.filter(order=>!["delivered","cancelled"].includes(order.status)).length;const signature=JSON.stringify(orders);if(signature===ordersSignature)return;ordersSignature=signature;$("#orders").innerHTML=orders.map(order=>`<article class="order-card" data-order="${order.id}"><div class="order-top"><h3>#${order.number}</h3><span class="order-stage ${order.status}">${names[order.status]}</span></div><p class="order-time">${new Date(order.createdAt).toLocaleString("pt-BR",{day:"2-digit",month:"2-digit",hour:"2-digit",minute:"2-digit"})} \xB7 ${order.preparationMinutes} min de preparo estimado</p><p><strong>${escape(order.customer)}</strong> \xB7 <a href="tel:${escape(order.phone.replace(/\D/g,""))}">${escape(order.phone)}</a></p><ul>${order.items.map(item=>`<li><strong>${item.quantity}\xD7 ${escape(item.name)}</strong> \xB7 ${money(item.total)}${item.extras.length?`<small>Adicionais por unidade: ${item.extras.map(extra=>`${escape(extra.name)} (+ ${money(extra.price)})`).join(", ")}</small>`:""}</li>`).join("")}</ul><div class="order-details"><p><strong>${order.fulfillment==="delivery"?"Entrega":"Retirada no trailer"}</strong>${order.address?`<br>${escape(order.address)}`:""}</p>${order.notes?`<p>Obs.: ${escape(order.notes)}</p>`:""}${order.deliveryFee?`<p>Entrega: ${money(order.deliveryFee)}</p>`:""}</div><div class="order-payment"><span>${money(order.total)} \xB7 ${{pix:"Pix",cash:"Dinheiro",card:"Maquininha"}[order.paymentMethod]}</span><span class="${order.paymentStatus}">${order.paymentStatus==="paid"?"Pago \u2713":"Pagamento pendente"}</span></div><div class="order-actions">${actions[order.status]?`<button class="primary" data-action="advance" data-id="${order.id}" ${order.status==="new"&&order.paymentTiming==="before"&&order.paymentStatus!=="paid"?"disabled":""}>${order.status==="new"&&order.paymentTiming==="before"&&order.paymentStatus!=="paid"?"Confirme o Pix para aceitar":actions[order.status]}</button>`:""}${order.status!=="cancelled"&&order.paymentStatus!=="paid"?`<button class="payment-action" data-action="pay" data-id="${order.id}">Confirmar recebimento</button>`:""}${["new","accepted"].includes(order.status)?`<button class="cancel-action" data-action="cancel" data-id="${order.id}">Cancelar</button>`:""}</div>${order.status==="cancelled"&&order.paymentStatus==="paid"?"<p>Pagamento recebido. Combine a devolu\xE7\xE3o com o cliente; cancelar n\xE3o estorna o dinheiro.</p>":""}</article>`).join("")||'<p class="empty-queue">Nenhum pedido na fila. Quando chegar um, ele aparece aqui.</p>'}function renderStore(){const shop=state.store;$("#panel-shop-summary").textContent=`${shop.open?"Loja aberta":"Loja fechada"} \xB7 ${shop.preparationMinutes} min de preparo \xB7 Entrega ${money(shop.deliveryFee)}`;const pix=shop.pix||{};$("#pix-enabled").checked=!!pix.enabled;$("#pix-key").value=pix.key||"";$("#pix-name").value=pix.name||"";$("#pix-city").value=pix.city||"";$("#shop-state").textContent=shop.open?"Loja aberta":"Loja fechada";$("#shop-state").classList.toggle("shop-open",shop.open);$("#toggle-open").textContent=shop.open?"FECHAR LOJA":"ABRIR LOJA";$("#preparation").value=shop.preparationMinutes;$("#delivery-fee").value=(shop.deliveryFee/100).toFixed(2);$("#availability").innerHTML=state.products.map(product=>`<label><input type="checkbox" value="${product.id}" ${shop.paused.includes(product.id)?"":"checked"}>${escape(product.name)}</label>`).join("")}async function refresh(initial=false){if(polling)return;polling=true;try{const next=await api("state");const arrivals=next.orders.filter(order=>!seen.has(order.id)&&order.status==="new");if(!firstLoad&&arrivals.length){beep();feedback(`${arrivals.length} novo(s) pedido(s) na fila!`)}next.orders.forEach(order=>seen.add(order.id));firstLoad=false;const previousVersion=state?.store.version;state=next;$("#login-section").hidden=true;$("#dashboard").hidden=false;$("#logout").hidden=false;$("#panel-nav").hidden=false;if(initial||previousVersion!==state.store.version)renderStore();renderOrders();await refreshMetrics();$("#connection").textContent=``;$("#connection").classList.remove("failed")}catch(error){if(state){$("#connection").textContent="Sem conex\xE3o. A fila ser\xE1 atualizada quando a conex\xE3o voltar.";$("#connection").classList.add("failed")}if(initial&&!state)feedback(error.message)}finally{polling=false}}function startPolling(){clearInterval(timer);timer=setInterval(()=>refresh(),5e3)}$("#login-form").addEventListener("submit",async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{await api("login","POST",{username:$("#username").value,password:$("#password").value});$("#password").value="";feedback("");firstLoad=true;await refresh(true);startPolling()}catch(error){feedback(error.message)}finally{button.disabled=false}});$("#logout").addEventListener("click",async()=>{try{await stopPush();await api("logout","POST",{});signedOut()}catch(error){feedback(error.message)}});$("#enable-sound").addEventListener("click",async()=>{try{audio||=new(window.AudioContext||window.webkitAudioContext);await audio.resume();beep();$("#enable-sound").textContent="Aviso sonoro ativado \u2713"}catch{feedback("Este navegador n\xE3o liberou o som. Os pedidos continuam aparecendo na fila.")}});async function saveStore(patch){state.store=await api("store","PATCH",{...state.store,...patch});renderStore();feedback("Loja atualizada.")}$("#toggle-open").addEventListener("click",async()=>{const button=$("#toggle-open");button.disabled=true;try{await saveStore({open:!state.store.open})}catch(error){feedback(error.message);await refresh(true)}finally{button.disabled=false}});$("#store-form").addEventListener("submit",async event=>{event.preventDefault();try{await saveStore({preparationMinutes:Number($("#preparation").value),deliveryFee:Math.round(Number($("#delivery-fee").value)*100)})}catch(error){feedback(error.message);await refresh(true)}});$("#save-products").addEventListener("click",async()=>{try{await saveStore({paused:[...$("#availability").querySelectorAll("input:not(:checked)")].map(input=>input.value)})}catch(error){feedback(error.message);await refresh(true)}});$("#show-history").addEventListener("change",renderOrders);$("#orders").addEventListener("click",async event=>{const button=event.target.closest("[data-action]");if(!button)return;const order=state.orders.find(item=>item.id===Number(button.dataset.id));if(!order)return;const action=button.dataset.action,patch={version:order.version};if(action==="pay"){if(!confirm(`Voc\xEA conferiu o recebimento de ${money(order.total)} do pedido #${order.number}? Comprovante sozinho n\xE3o confirma Pix.`))return;patch.paymentStatus="paid"}if(action==="cancel"){if(!confirm(`Cancelar o pedido #${order.number}?${order.paymentStatus==="paid"?" Isso n\xE3o devolve o pagamento. Combine a devolu\xE7\xE3o com o cliente.":""}`))return;patch.status="cancelled"}if(action==="advance"){patch.status=stages[stages.indexOf(order.status)+1];if(patch.status==="delivered"&&!confirm(`Tem certeza que o pedido #${order.number} foi entregue ao cliente? Ele vai sair da fila e ficar no hist\xF3rico.`))return}button.disabled=true;try{await api(`orders/${order.id}`,"PATCH",patch);feedback("Pedido atualizado.");await refresh()}catch(error){feedback(error.message);await refresh()}finally{button.disabled=false}});function today(){return new Date().toLocaleDateString("en-CA",{timeZone:"America/Sao_Paulo"})}$("#metrics-date").value=today();let metricsBusy=false;async function refreshMetrics(){if(metricsBusy||!state)return;metricsBusy=true;const date=$("#metrics-date").value;try{const m=await api("metrics?date="+encodeURIComponent(date));if($("#metrics-date").value!==date)return;window.dispatchEvent(new CustomEvent("renato:metrics",{detail:m}));const cards=[["Recebido",m.received,"Pagamentos marcados como recebidos"],["Lanches e comidas",m.foodReceived,"Recebido sem as taxas de entrega"],["Taxas de entrega",m.deliveryFees,"Parte do recebido, n\xE3o uma cobran\xE7a extra"],["Sa\xEDdas registradas",m.spent,"Gastos informados pelo Renato"],["Saldo registrado",m.balance,"Recebido menos sa\xEDdas; n\xE3o \xE9 lucro"]];$("#metrics-cards").innerHTML=cards.map(([label,value,note])=>`<article class="metric-card"><span>${label}</span><strong>${money(value)}</strong><small>${note}</small></article>`).join("")+`<article class="metric-card"><span>Movimento do dia</span><strong>${m.delivered} entregues</strong><small>${m.created} pedidos chegaram \xB7 ${m.paidCount} pagamentos confirmados</small></article>`;$("#expense-list").innerHTML=m.expenses.length?`<details><summary>Sa\xEDdas do dia (${m.expenses.length})</summary><ul>${m.expenses.map(e=>`<li>${escape(e.description)} <strong>${money(e.amount)}</strong> \xB7 ${new Date(e.created_at).toLocaleTimeString("pt-BR",{timeZone:"America/Sao_Paulo",hour:"2-digit",minute:"2-digit"})}</li>`).join("")}</ul></details>`:""}catch(error){feedback(error.message)}finally{metricsBusy=false}}$("#metrics-date").addEventListener("change",()=>refreshMetrics());let pendingExpense;$("#expense-form").addEventListener("submit",async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{const amount=Math.round(Number($("#expense-amount").value)*100),description=$("#expense-description").value;if(!pendingExpense||pendingExpense.amount!==amount||pendingExpense.description!==description)pendingExpense={amount,description,requestKey:crypto.randomUUID()};await api("expenses","POST",pendingExpense);pendingExpense=void 0;event.target.reset();$("#metrics-date").value=today();await refreshMetrics();feedback("Sa\xEDda registrada no caixa de hoje.")}catch(error){feedback(error.message)}finally{button.disabled=false}});$("#change-password-form").addEventListener("submit",async event=>{event.preventDefault();if($("#new-password").value!==$("#repeat-password").value){feedback("As duas novas senhas precisam ser iguais.");return}const button=event.submitter;button.disabled=true;try{await api("password","POST",{currentPassword:$("#current-password").value,newPassword:$("#new-password").value});event.target.reset();signedOut();feedback("Senha alterada. Entre novamente com a nova senha.")}catch(error){feedback(error.message)}finally{button.disabled=false}});$("#pix-config-form").addEventListener("submit",async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{await api("pix","POST",{enabled:$("#pix-enabled").checked,key:$("#pix-key").value,name:$("#pix-name").value,city:$("#pix-city").value,currentPassword:$("#pix-password").value});$("#pix-password").value="";await refresh(true);feedback("Pix atualizado. Confira o QR Code no aplicativo do banco antes de usar com clientes.")}catch(error){feedback(error.message)}finally{button.disabled=false}});await refresh();if(state)startPolling();
